custom_css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&family=Pinyon+Script&family=Silkscreen:wght@400;700&family=Space+Mono:ital,wght@0,400;0,700;1,400&display=swap');

/* обязательное: палитра для ВСЕХ окон */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
  --t-bg: #f4f2ee;
  --t-bg-alt: #eae7e1;
  --t-paper: #ffffff;
  --t-ink: #121212;
  --t-dim: #686662;
  --t-line: rgba(18, 18, 18, 0.22);
  --t-red: #d91e2a;
  --t-blue: #1e5cd9;
  --mt-bg-primary: var(--t-bg);
  --mt-bg-secondary: var(--t-bg-alt);
  --mt-bg-input: var(--t-paper);
  --mt-accent: var(--t-ink);
  --mt-accent-hover: var(--t-red);
  --mt-border: var(--t-line);
  --mt-text: var(--t-ink);
  --mt-text-dim: var(--t-dim);
  --mt-text-on-accent: #f4f2ee;
  --mt-overlay: rgba(14, 14, 16, 0.55);
  --mt-modal-shadow: 6px 6px 0px rgba(18, 18, 18, 0.9);
  --mt-text-strong: var(--t-ink);
  --mt-divider: var(--t-line);
  --mt-pl-spotify-tab: var(--t-ink);
  --mt-pl-spotify-tab-text: #f4f2ee;
}

.mt-progress {
  --mt-slider-track: #d5d2cc;
  --mt-slider-track-height: 3px;
  --mt-slider-track-radius: 0px;
  --mt-slider-thumb-size: 10px;
  --mt-slider-thumb-bg: var(--t-paper);
  --mt-slider-thumb-bg-hover: var(--t-red);
  --mt-slider-thumb-border: 2px solid var(--t-ink);
  --mt-slider-thumb-radius: 0px;
  --mt-slider-thumb-shadow: none;
  --mt-slider-progress: var(--t-ink);
}

.mt-volume {
  --mt-slider-track: #d5d2cc;
  --mt-slider-track-height: 2px;
  --mt-slider-track-radius: 0px;
  --mt-slider-thumb-size: 8px;
  --mt-slider-thumb-bg: var(--t-ink);
  --mt-slider-thumb-bg-hover: var(--t-red);
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 0px;
  --mt-slider-thumb-shadow: none;
  --mt-slider-progress: var(--t-ink);
}

/* обязательное: плеер (БЕЗ position/top/left/width/height) */
.mt-player {
  container-type: size;
  padding: 38px 16px 14px;
  background-color: var(--t-bg);
  background-image:
    radial-gradient(rgba(18, 18, 18, 0.05) 1px, transparent 0),
    linear-gradient(135deg, rgba(255, 255, 255, 0.6) 0%, rgba(230, 226, 218, 0.4) 100%);
  background-size: 16px 16px, 100% 100%;
  border: 1.5px solid var(--t-ink);
  border-radius: 6px;
  color: var(--t-ink);
  font-family: 'Space Mono', 'Inter', monospace;
  box-shadow: 5px 5px 0px var(--t-ink);
  backdrop-filter: none;
}

.mt-player * {
  font-family: inherit;
}

.mt-player i {
  font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome;
}

/* тени и свечение текста из темы SillyTavern выключаем селектором с id */
#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal * {
  text-shadow: none;
}

/* Декор-слот опускаем под контент, чтобы не перекрывал текст */
.mt-slot-decor {
  z-index: 1;
  pointer-events: none;
}

.mt-slot-scene::before {
  content: '★';
  position: absolute;
  top: 38px;
  left: 16px;
  font-size: 11px;
  color: var(--t-dim);
  opacity: 0.6;
  pointer-events: none;
}

.mt-slot-scene::after {
  content: '♥';
  position: absolute;
  bottom: 44px;
  right: 16px;
  font-size: 10px;
  color: var(--t-ink);
  opacity: 0.5;
  pointer-events: none;
}

/* Шапка */
.mt-player-header {
  top: 10px;
  left: 14px;
  right: 96px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.mt-player-header-title {
  font-family: 'Silkscreen', monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: var(--t-ink);
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mt-player-status {
  font-family: 'Space Mono', monospace;
  font-size: 9px;
  color: var(--t-ink);
  background: var(--t-paper);
  border: 1px solid var(--t-ink);
  padding: 1px 5px;
  border-radius: 0;
  text-transform: lowercase;
  white-space: nowrap;
}

.mt-player.mt-is-playing .mt-player-status {
  background: var(--t-ink);
  color: var(--t-bg);
}

/* Кнопки окна в правом верхнем углу */
.mt-window-btn {
  color: var(--t-ink);
  opacity: 0.75;
  transition: opacity 0.15s, color 0.15s;
}

.mt-window-btn:hover {
  opacity: 1;
  color: var(--t-red);
}

/* Тело плеера */
.mt-player-body {
  gap: 10px;
}

/* Обложка: виниловая пластинка + квадратный постер трека */
@keyframes mt-vinyl-spin {
  to { rotate: 360deg; }
}

.mt-cover {
  position: relative;
  width: 126px;
  height: 126px;
  border-radius: 50%;
  overflow: visible;
  border: none;
  box-shadow: none;
  flex-shrink: 0;
  margin: 2px auto;
}

/* Виниловый диск на фоне обложки */
.mt-slot-cover-bg {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background:
    radial-gradient(circle at center, var(--t-bg) 0 13%, var(--t-ink) 13.5% 15%, #dfd9ce 15.5% 24%, var(--t-ink) 24.5% 100%),
    repeating-radial-gradient(circle at center, #121212 0px, #121212 2px, #242424 3px, #121212 4px);
  background-blend-mode: normal;
  border: 2px solid var(--t-ink);
  box-shadow: 0 3px 0 rgba(18, 18, 18, 0.18);
  z-index: 0;
  animation: mt-vinyl-spin 14s linear infinite;
  animation-play-state: paused;
}

.mt-player.mt-is-playing .mt-slot-cover-bg {
  animation-play-state: running;
}

/* Настоящая обложка трека: постер поверх винила */
.mt-cover img.mt-cover-img {
  position: absolute;
  width: 78px;
  height: 78px;
  top: 24px;
  left: 24px;
  border-radius: 2px;
  object-fit: cover;
  border: 3px solid var(--t-paper);
  outline: 1px solid var(--t-ink);
  box-shadow: 3px 3px 0px rgba(18, 18, 18, 0.85);
  rotate: -5deg;
  transition: rotate 0.25s ease, scale 0.25s ease;
  z-index: 1;
}

.mt-player.mt-is-playing .mt-cover img.mt-cover-img {
  rotate: -2deg;
}

.mt-cover:hover img.mt-cover-img {
  rotate: 0deg;
  scale: 1.03;
}

/* Прозрачный слот поверх обложки с аккуратным номером как на референсе */
.mt-slot-cover {
  position: absolute;
  inset: 0;
  background: transparent;
  pointer-events: none;
  z-index: 2;
}

.mt-slot-cover::after {
  content: '01';
  position: absolute;
  bottom: 4px;
  left: 10px;
  font-family: 'Silkscreen', monospace;
  font-size: 9px;
  color: var(--t-paper);
  background: var(--t-ink);
  padding: 0px 3px;
  border: 1px solid var(--t-paper);
}

.mt-cover-hole {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--t-bg);
  border: 1.5px solid var(--t-ink);
  z-index: 3;
  opacity: 0.85;
  pointer-events: none;
}

/* Информация о треке в стиле рамки выделения графического редактора */
.mt-track-info {
  position: relative;
  width: 100%;
  box-sizing: border-box;
  padding: 5px 26px 5px 10px;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid var(--t-ink);
  text-align: center;
}

.mt-track-info::before,
.mt-track-info::after {
  content: '';
  position: absolute;
  width: 5px;
  height: 5px;
  background: var(--t-paper);
  border: 1px solid var(--t-ink);
  pointer-events: none;
}

.mt-track-info::before {
  top: -3.5px;
  left: -3.5px;
}

.mt-track-info::after {
  bottom: -3.5px;
  right: -3.5px;
}

.mt-track-title {
  font-family: 'Space Mono', monospace;
  font-size: 12px;
  font-weight: 700;
  color: var(--t-ink);
  letter-spacing: -0.3px;
  line-height: 1.25;
}

.mt-track-subtitle {
  font-family: 'Pinyon Script', cursive;
  font-size: 16px;
  color: var(--t-dim);
  line-height: 1.1;
  margin-top: 1px;
}

/* Кнопка избранного (только цвет, без фона и рамки) */
.mt-btn-favorite {
  background: none;
  border: none;
  box-shadow: none;
  color: var(--t-dim);
  right: 6px;
}

.mt-btn-favorite:hover {
  color: var(--t-ink);
}

.mt-btn-favorite.mt-is-active {
  color: var(--t-red);
}

/* Прогресс и время */
.mt-progress {
  width: 100%;
  gap: 6px;
}

.mt-time-current,
.mt-time-total {
  font-family: 'Silkscreen', monospace;
  font-size: 9px;
  color: var(--t-ink);
}

/* Кнопки управления */
.mt-controls {
  gap: 8px;
}

.mt-controls > .mt-btn {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  font-size: 13px;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--t-paper);
  color: var(--t-ink);
  border: 1.5px solid var(--t-ink);
  box-shadow: 2px 2px 0px var(--t-ink);
  transition: translate 0.1s ease, background-color 0.15s ease, color 0.15s ease;
}

.mt-controls > .mt-btn:hover {
  background: var(--t-bg-alt);
  translate: -1px -1px;
}

.mt-controls > .mt-btn:active {
  translate: 1px 1px;
  box-shadow: 0px 0px 0px var(--t-ink);
}

.mt-controls > .mt-btn.mt-btn-play {
  width: 40px;
  height: 40px;
  font-size: 14px;
  background: var(--t-ink);
  color: var(--t-bg);
  border-color: var(--t-ink);
}

.mt-controls > .mt-btn.mt-btn-play:hover {
  background: var(--t-red);
  border-color: var(--t-ink);
  color: #ffffff;
}

.mt-btn-play.fa-play {
  padding-left: 2px;
}

.mt-controls > .mt-btn.mt-btn-ai.mt-is-busy {
  background: var(--t-blue);
  color: #ffffff;
}

/* Громкость */
.mt-volume {
  width: 100%;
  gap: 6px;
}

.mt-volume-low,
.mt-volume-high {
  color: var(--t-dim);
  font-size: 11px;
}

/* обязательное: панели, окна */
.mt-panel {
  background: var(--t-bg);
  color: var(--t-ink);
  padding-top: 40px;
  border-radius: inherit;
}

.mt-panel-search {
  --mt-bg-primary: var(--t-bg);
}

.mt-panel-header {
  border-bottom: 1.5px solid var(--t-ink);
  padding-bottom: 6px;
  margin-bottom: 6px;
}

.mt-panel-title {
  font-family: 'Silkscreen', monospace;
  font-size: 11px;
  text-transform: uppercase;
  color: var(--t-ink);
}

.mt-panel-close {
  color: var(--t-ink);
}

.mt-panel-close:hover {
  color: var(--t-red);
}

/* Очередь в стиле треклиста 01..05 */
.mt-panel-list {
  counter-reset: mt-tracklist;
}

.mt-queue-item {
  counter-increment: mt-tracklist;
  border-bottom: 1px dashed var(--t-line);
  padding: 6px 8px;
  border-radius: 0;
  background: transparent;
  transition: background-color 0.15s;
}

.mt-queue-item::before {
  content: counter(mt-tracklist, decimal-leading-zero);
  font-family: 'Silkscreen', monospace;
  font-size: 10px;
  color: var(--t-dim);
  margin-right: 8px;
  flex-shrink: 0;
}

.mt-queue-item:hover {
  background: rgba(18, 18, 18, 0.06);
}

.mt-queue-item.mt-is-current {
  background: var(--t-paper);
  border: 1px solid var(--t-ink);
  font-weight: 700;
}

.mt-queue-item.mt-is-current::before {
  color: var(--t-red);
}

.mt-queue-thumb {
  border-radius: 2px;
  border: 1px solid var(--t-ink);
}

.mt-queue-title {
  color: var(--t-ink);
  font-family: 'Space Mono', monospace;
  font-size: 11px;
}

/* Запрет 4: только color для .mt-queue-add / .mt-queue-now / .mt-queue-empty */
.mt-queue-now {
  color: var(--t-red);
}

.mt-queue-add {
  color: var(--t-ink);
}

.mt-queue-add:hover {
  color: var(--t-blue);
}

.mt-queue-dislike {
  background-color: var(--t-dim);
}

.mt-queue-dislike:hover {
  background-color: var(--t-red);
}

.mt-queue-empty {
  color: var(--t-dim);
}

/* Плейлисты */
.mt-pl-tabs {
  border-bottom: 1.5px solid var(--t-ink);
  gap: 4px;
}

.mt-pl-tab {
  font-family: 'Silkscreen', monospace;
  font-size: 10px;
  color: var(--t-dim);
  background: var(--t-bg-alt);
  border: 1px solid var(--t-ink);
  border-bottom: none;
  border-radius: 3px 3px 0 0;
}

.mt-pl-tab.mt-is-active {
  background: var(--t-ink);
  color: var(--t-bg);
}

.mt-playlist-item {
  border-bottom: 1px dashed var(--t-line);
  border-radius: 0;
}

.mt-playlist-item:hover {
  background: rgba(18, 18, 18, 0.06);
}

.mt-playlist-title {
  color: var(--t-ink);
  font-weight: 700;
}

.mt-pl-count {
  color: var(--t-dim);
  font-family: 'Silkscreen', monospace;
  font-size: 9px;
}

.mt-pl-cover {
  border: 1px solid var(--t-ink);
  border-radius: 2px;
}

.mt-pl-tool {
  background: var(--t-paper);
  color: var(--t-ink);
  border: 1px solid var(--t-ink);
}

.mt-pl-tool.mt-pl-play,
.mt-pl-tool:hover {
  background: var(--t-ink);
  color: var(--t-bg);
}

/* Поиск (форму не трогаем, задаём контрастные цвета) */
#moodtube-search-input {
  background: var(--t-paper);
  color: var(--t-ink);
  border-color: var(--t-ink);
}

#moodtube-search-go {
  background: var(--t-ink);
  color: var(--mt-text-on-accent);
}

#moodtube-search-go:hover {
  background: var(--t-red);
}

/* Плавающая кнопка .mt-fab */
.mt-fab {
  background: var(--t-paper);
  color: var(--t-ink);
  border: 1.5px solid var(--t-ink);
  box-shadow: 3px 3px 0px var(--t-ink);
}

.mt-fab:hover {
  background: var(--t-ink);
  color: var(--t-bg);
}

/* Модальное окно добавления в плейлист (красим только .mt-pl-modal-box) */
.mt-pl-modal-box {
  background: var(--t-bg);
  color: var(--t-ink);
  border: 1.5px solid var(--t-ink);
  border-radius: 6px;
  box-shadow: 6px 6px 0px var(--t-ink);
  font-family: 'Space Mono', monospace;
}

.mt-pl-modal-track {
  color: var(--t-ink);
  border-bottom: 1px dashed var(--t-line);
}

.mt-pl-option {
  color: var(--t-ink);
  border: 1px solid transparent;
}

.mt-pl-option:hover {
  background: var(--t-bg-alt);
  border-color: var(--t-ink);
}

.mt-pl-option.mt-is-added {
  background: var(--t-ink);
  color: var(--t-bg);
}

/* Окно настроек #mt-settings-modal */
#mt-settings-modal .mt-flex-container {
  background: var(--t-bg);
  color: var(--t-ink);
  border: 1.5px solid var(--t-ink);
  border-radius: 6px;
  box-shadow: 6px 6px 0px var(--t-ink);
  font-family: 'Space Mono', 'Inter', monospace;
}

#mt-settings-modal .mt-header h3 {
  font-family: 'Silkscreen', monospace;
  color: var(--t-ink);
  text-transform: uppercase;
}

#mt-settings-modal .mt-close {
  color: var(--t-ink);
}

#mt-settings-modal .mt-close:hover {
  color: var(--t-red);
}

#mt-settings-modal .mt-subpanel {
  background: var(--t-paper);
  border: 1px solid var(--t-ink);
  border-radius: 4px;
}

#mt-settings-modal .mt-tag,
#mt-settings-modal .mt-genre-tag,
#mt-settings-modal .mt-mood-tag,
#mt-settings-modal .mt-scenario-tag {
  background: var(--t-paper);
  color: var(--t-ink);
  border: 1px solid var(--t-ink);
  border-radius: 2px;
}

#mt-settings-modal .mt-tag:hover,
#mt-settings-modal .mt-genre-tag:hover,
#mt-settings-modal .mt-mood-tag:hover,
#mt-settings-modal .mt-scenario-tag:hover {
  background: var(--t-bg-alt);
}

#mt-settings-modal .mt-tag.active,
#mt-settings-modal .mt-genre-tag.active,
#mt-settings-modal .mt-mood-tag.active,
#mt-settings-modal .mt-scenario-tag.active {
  background: var(--t-ink);
  color: var(--t-bg);
  border-color: var(--t-ink);
}

#mt-settings-modal .mt-btn-test,
#mt-settings-modal button[type="submit"],
#mt-settings-modal .mt-btn-save {
  background: var(--t-ink);
  color: var(--t-bg);
  border: 1px solid var(--t-ink);
  border-radius: 2px;
  font-weight: 700;
}

#mt-settings-modal .mt-btn-test:hover,
#mt-settings-modal button[type="submit"]:hover,
#mt-settings-modal .mt-btn-save:hover {
  background: var(--t-red);
  color: #ffffff;
}

/* Scrollbar для светлой темы */
.mt-player ::-webkit-scrollbar,
#mt-settings-modal ::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

.mt-player ::-webkit-scrollbar-track,
#mt-settings-modal ::-webkit-scrollbar-track {
  background: var(--t-bg-alt);
}

.mt-player ::-webkit-scrollbar-thumb,
#mt-settings-modal ::-webkit-scrollbar-thumb {
  background: var(--t-ink);
}

/* ================= АДАПТИВ И РЕЖИМЫ ================= */

/* Широкая строка (.moodtube-row-layout) — специфичность >= (0,3,0) */
.mt-player.moodtube-row-layout#moodtube-mini-player {
  padding: 32px 14px 10px;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body {
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover {
  width: 52px;
  height: 52px;
  margin: 0;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover img.mt-cover-img {
  width: 34px;
  height: 34px;
  top: 9px;
  left: 9px;
  border-width: 2px;
  box-shadow: 2px 2px 0px rgba(18, 18, 18, 0.85);
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-slot-cover::after,
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover-hole {
  display: none;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-track-info {
  min-width: 105px;
  max-width: 150px;
  flex: 0 1 135px;
  text-align: left;
  padding: 3px 22px 3px 7px;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-track-subtitle {
  font-size: 13px;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-progress {
  flex: 1 1 90px;
  min-width: 90px;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls {
  gap: 4px;
  flex-shrink: 0;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn {
  width: 28px;
  height: 28px;
  font-size: 12px;
  box-shadow: 1px 1px 0px var(--t-ink);
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn.mt-btn-play {
  width: 34px;
  height: 34px;
  font-size: 13px;
}

.mt-player.moodtube-row-layout#moodtube-mini-player .mt-volume {
  width: 76px;
  flex-shrink: 0;
}

/* Контейнерные запросы */
@container (max-width: 300px) {
  .mt-player .mt-player-status {
    display: none;
  }
}

@container (max-width: 640px) {
  .mt-player.moodtube-row-layout .mt-volume {
    display: none;
  }
}

/* Маленький квадрат (200x200) и компактные состояния по высоте */
@container (max-height: 290px) {
  .mt-player:not(.moodtube-row-layout) .mt-cover {
    width: 84px;
    height: 84px;
  }
